import{_ as p,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"易纂言","description":"易纂言 - 易纂言","frontmatter":{"title":"易纂言","description":"易纂言 - 易纂言"},"headers":[],"relativePath":"classics/zuanyan/001.md","filePath":"classics/zuanyan/001.md"}'),n={name:"classics/zuanyan/001.md"};function r(c,a,_,i,o,l){return t(),e("div",null,[...a[0]||(a[0]=[s('<h1 id="易纂言" tabindex="-1">易纂言 <a class="header-anchor" href="#易纂言" aria-label="Permalink to “易纂言”">​</a></h1><p>欽定四庫全書經部一</p><p>易類提要</p><p>臣 等謹案：易纂言十二卷，元吳澄撰。字幼清，號草廬，崇仁人。宋鹹淳末舉進士不第，入元以薦擢翰林應奉文字，官至翰林學士，卒諡文正。事蹟具元史本傳。是書用呂祖謙古易本。經文每卦先列卦變主爻，每爻先列變爻，次列象佔十翼亦各分章數。其訓解各附句下，音釋、考證則經附每卦之末，傳附每章之末。間有文義相因，即附辨於句下者，偶一二見，非通例也。澄於諸經好臆為點竄，惟此書所改，則有根據者為多。如師卦「丈人吉」改「大人吉」，據崔憬所引子夏傅本；比卦「比之匪人」下增「兇」字，據王肅本；小畜卦「輿說輻」改「輿說輹」，據許慎說文。「尚德載」改「尚得載」，據京房、虞翻、子夏本。泰卦「包荒」改「包巟」，據說文及虞翻本。大畜卦「曰閒輿衛」改「日閒輿衛」，從鄭元、虞翻、陸希聲本；萃卦「萃亨」刪「亨」字。從馬融、鄭元、虞翻、陸績本。困卦「劓刖」改「臲卼」。據荀爽、王肅、陸績本。鼎卦「其形渥」改「其刑剭」。據鄭元本。比彖「比吉也」刪「也」字。據王昭素本。賁彖補「剛柔交錯」四字。據王弼注。震彖「驚遠而慎邇也」下補「不喪匕鬯」四字。據王昭素所引徐氏本。漸彖「女歸吉也」改「女歸吉利貞」。據王肅本。坤象「履霜堅冰」改「初六履霜」。據魏志。坎象「樽酒簋貳」刪「貳」字。據陸德明釋文。 案：澄註明言舊本有「貳」字，陸氏釋文無之，今世所行張弧、陸希聲本皆同，是傅文已刪去「貳」字。徐氏通志堂本乃劖補刊板，增入「貳」字，是顧湄等校正之時以不誤為誤也。謹附識於此。 繋辭上傅「繋辭焉而明吉凶」下補「悔吝」二字。據虞翻本。繋辭下傅「何以守位曰仁」改「何以守位曰人」。據王肅本。「耒耨之利」改「耒耨之地」。據王昭素本。「以濟不通」下刪「致遠以利天下」六字。據陸德明釋文序卦傳；「故受之以履」下補「履者禮也」四字，據韓康伯本。皆據引古義，具有源流，不比師心變亂。其餘亦多依傍胡瑗、程子、朱子諸說。澄所自改正者，不過數條而已。惟以繋辭傅中說上下經十六卦十八爻之文，定為錯簡，移置於文言傅中，則悍然臆斷，不可以為訓矣。然其解釋經義，詞簡理明，融貫舊聞，亦頗賅洽，在元人說易諸家，固終為巨擘焉。乾隆四十六年九月恭校上。</p><p>總纂官 臣 紀昀、 臣 陸錫熊、 臣 孫士毅，總校官 臣 陸費墀。欽定四庫全書易纂言卷首元吳澄撰</p><p>易</p><p>易者，陰易相變易也。上古包羲氏，見天地萬物之性情形體，一易一陰而已，於是作一奇畫以象陽，作一耦畫以象陰。見一陽一陰之互相易也，故自一奇一耦相易而為四象八卦，極於六十四卦，是為卦畫之象。又作揲蓍之法，教民以卦而佔吉凶，自一變而極於十有八變，是為蓍數之變。卦象、蓍變皆以陰陽相易，故名之曰「易」。其時未有「易」字也，後之造字者，合「日」「月」二文而為「易」字。日，陽精昱乎畫；月，陰精昱乎夜。日往則月來，月往則日來，陰陽相易而成晝夜，故「易」從「日」從「月」。字書乂謂「易」字象蜥蜴之形，而假借為「變易」之「易」，蓋不然也。禮記曰：「昔者聖人達陰陽天地之情，立以為易。」 □□</p><p>羲皇畫卦之時，先作此一畫。一者為奇，陽之象也；一者為耦，陰之象也。陽渾合無間，故「一」；陰受衡即開，故「二」。後人名之為兩儀。繫辭傳曰：「易有太極，是生兩儀。」邵子謂：一分為二。朱子謂：一奇一耦為一畫者，二是也。其畫一，其位二，其奇耦之數三。 □□□□，</p><p>奇耦一畫之上再加一奇一耦，以象陰陽之有老少。「奇」上加「奇」者，陽之純，故象老陽；奇上加耦者，陰雜於陽中，故象少陰；耦上加奇者，陽雜於陰中，故象少陽。耦上加耦者，陰之純，故象老陰。後人名之為「四象」。繫辭傳曰：「兩儀生四象。」邵子謂「二分為四」。朱子謂兩儀八，各生奇耦，為二畫者，四是也。其畫二，其位四，其積畫其奇耦之數十二。蓋一畫加一為二，其位則倍二為四也。 ☰☱☲☳☴☵☶☷ 二畫之上又各加一奇一耦，奇奇之上加一奇，象天，而名「乾」。奇奇之上加一耦，象澤，而名「兌」。奇耦之上加一奇，象日象火，而名「離」。奇耦之上加一耦，象雷，而名「震」。耦奇之上加一奇，象風，而名「巽」。耦奇之上加一耦，象月象水，而名「坎」。耦耦之上加一奇，象山，而名「艮」。耦耦之上加一耦，象地，而名「坤」。乾一、兌二、離三、震四、巽五、坎六、艮七、坤八，總名之曰「八卦」。然當時未有乾、兌、離、震、巽、坎、艮、坤八字及卦字也。即此各卦三畫之象，而名為「乾」，名為「兌」，名為「離」，名為「震」，名為「巽」，名為「坎」，名為「艮」，名為「坤」也。天、地、山、澤、日月、水火、雷風，亦有其名，而未有其字。繫辭傳曰：「四象生八卦，</p><p>八卦成列，象在其中矣。」邵子謂：四分為八。朱子謂：四象各生奇耦，為三畫者八是也。其畫三，其位八，其積畫二十四，其奇耦之數三十六。蓋二畫加一為三，其位則倍四為八也。畫至三而卦有八，為卦之小成，三才之象具矣。故定為此圖。直豎則乾上坤下，離左坎右，震左後，兌左前，巽右前，艮右後。平布則乾南坤北，離東坎西，震東北，兌東南，巽西南，艮西北。繫辭傳曰：「天尊地卑，乾坤定矣。」說卦傳曰：「天地定位，山澤通氣，雷風相薄，水火不相射。」謂此圖也。邵子曰：太極既分，兩儀立矣。陽下交於陰，陰上交於陽，四象生矣。陽交於陰，陰交於陽，而生天之四象；剛交於柔，柔交於剛，而生地之四象。於是八卦成矣。乾以分之，坤以翕之，震以長之，巽以消之。長則分，分則消，消則翕也。乾坤，定位也。震、巽，一交也，兌、離、坎、艮，再交也。震，陽少而陰尚多也，巽，陰少而陽尚多也。兌、離，陽浸多也，坎、艮，陰浸多也。乾坤之名位不可易也，坎、離，名可易而位不可易也，震、巽，位可易而名不可易也，兌、艮，名與位皆可易也。離在天而當夜，故陽中有陰也；坎在地而當晝，故陰中有陽也。震始交陰而陽生，巽始消陽而陰生。兌，陽長也；艮，陰長也。震、兌，在天之陰也，巽、艮，在地之陽也。故震、兌上陰而下陽，巽艮上陽而下陰。天以始生言之，故陰上而陽下，交泰之義也；地以既成言之，故陽上而陰下，尊卑之位也。順數之，乾一、兌二、離三、震四、巽五、坎六、艮七、坤八；逆數之，震一、離兌二、乾三、巽四、坎艮五、坤六也。乾坤定上下之位，離坎列左右之門，天地之所闔闢，日月之所出入，是以春夏秋冬，晦朔弦望，畫夜長短、行度盈縮，莫不由乎此矣。乾坤縱而六子衡，易之本也。 □□□□□□□□□□□□□□□□， 三畫之上又各加一奇一耦，邵子謂八分為十六，朱子謂八卦各生奇耦，為四畫者十六。兩儀之上加八卦，八卦之上加兩儀是也。其畫四，其位十六，其積畫六十四，其奇耦之數九十六，蓋三畫加一為四，而其位則倍八為十六也。 □□□□□□□□□□□䷲□□□□□□□□□□□□□□□□□□□□， 四畫之上又各加一奇一耦，邵子謂十六分為三十二，朱子謂四畫各生奇耦，為五畫者三十二。四象之上加八卦，八卦之上加四象是也。其畫五，其位三十二，其積畫一百六十，其奇耦之數二百四十，蓋四畫加一為五，其位則倍十六為三十二也。 ䷉䷪䷍䷡䷈䷄䷙䷊䷉䷹䷥䷵䷼䷻䷨䷒䷌䷰䷝䷶䷤䷾䷕䷣䷘䷐䷔䷲䷩䷂䷚䷗䷫䷛䷱䷟䷸䷭䷑䷭䷅䷮䷿䷧䷺䷜䷃䷆䷠䷞䷷䷽䷴䷦䷳䷎䷋䷬䷢䷏䷓䷇䷖䷁ 五畫之上又各加一奇一耦，邵子謂三十二分為六十四，朱子謂五畫各生奇耦，為六畫者六十四。蔡氏謂，八卦重為六十四卦，一卦之上各有八卦是也。其畫六，其位六十四，其積畫三百八十四，其奇耦之數五百七十六。蓋五畫加一為六，其位則倍三十二為六十四也。邵子曰：一變而二，二變而四，三變而八卦成矣。四變而十有六，五變而三十有二，六變而六十四卦備矣。畫至六而卦有六十四，為卦之大成。兼三才而兩之，萬物萬事悉備矣。故又為此圖，以圓函方。圓者，象天周地外，方者，象地在天中。說卦傳曰：「八卦相錯，數往者順，知來者逆。」謂此圖也。邵子曰：八卦相交錯而成六十四卦。數往者，若順天而行，是左旋也，皆已生之卦也。「知來」者，若逆天而行，是右行也，皆未生之卦也。無極之前，陰含陽也；有象之後，陽分陰也。陰為陽之母，陽為陰之父。故母孕長男而為復，父生長女而為姤。是以陽起於復，陰起於姤也。夫易根於乾坤，而生於姤復，蓋剛交柔而為復，柔交剛而為姤，自茲而無窮矣。復至乾，凡百有十二陽；姤至坤，凡八十陽；姤至坤，凡百有十二陰；復至乾，凡八十陰。陽在陰中，陽逆行；陰在陽中，陰逆行。陽在陽中，陰在陰中，則皆順行。此真至理，案圖可見之矣。邵氏曰：「此圖圓布者，乾盡午中，坤儘子中，離盡卯中，坎盡酉中。陽生於子中，極於午中；陰生於午中，極於子中。其陽在南，其陰在北。方布者，乾始於西北，坤盡於東南，其陽在北，其陰在南。二者陰陽對待之數。圖於外者為陽，方於中者為陰。圓者動而為天，方者靜而為地也。」</p><p>右羲皇之易。昔在羲皇，始畫八卦，因而重之為六十四。當是時，易有圖而無書也。後聖因之作連山，作歸藏，作周易，雖一本諸羲皇之圖，而其取用蓋各不同焉。三易既亡其二，而周易獨存，世儒誦習，知有周易而已。羲皇卦圖鮮或傳授，而淪落於方伎家，雖其說具見於夫子之繫辭、說卦，而讀者莫之察也。至宋邵子始得而發揮之，於是人乃知有羲皇之易，而學易者不斷自文王、周公始也。今於易之一經，首揭此圖，冠於經端，以為羲皇之易，而後以三易繼之，蓋欲使夫學者知易之本源，不至尋流逐末而昧其所自云爾。 以上凡八圖。其八卦定位、六十四卦方圓凡二圖，邵子得之於李之才挺之，李得之穆修伯長，穆得之希夷先生陳摶圖南。蓋羲皇八卦、重卦既成之後，作此二圖也。儒者不傳，而方伎家傳之，以為修養火候之節。其一畫、二畫、三畫、四畫、五畫、六畫，凡六圖，則朱子推而得之，載於易學啟蒙。雖失其傳授所自，然考夫子繫辭傳所言，及邵子觀物外篇所推，則古有此圖也必矣。蓋羲皇未作八卦定位、重卦方圓二圖之時，先有此圖也。故今定此以為羲皇之易雲。 易連山䷳ 艮下艮上。</p><p>此連山易之首卦也。以下六十三卦先後之次不可知。 右夏之易。周官：「大卜掌三易，一曰連山，二曰歸藏，三曰周易。其經卦皆八，其別皆六十有四。」或曰：神農作連山，夏因之，以其首艮，故曰連山，今亡。歸藏䷁ 坤下坤上。</p><p>此歸藏易之首卦也。以下六十三卦先後之次不可知。 右商之易。子曰：「我欲觀殷道，是故之宋，而不足徵也，吾得坤乾焉。」說者以坤乾為歸藏。或曰：黃帝作歸藏，商因之，以其首坤，故曰歸藏，今亡。 案，夏、商二易，蓋因羲皇所畫之卦而用之以占筮，卦序與先天自然之序不同，故連山首艮，歸藏首坤。朱子易贊曰：「降帝而王，傳夏曆商，有佔無文，民用弗彰。」以為二易無繇辭也。或曰，春秋左氏傳所載繇辭與周易不同者，蓋夏、商之易，則以為有繇辭矣，然今莫可考證。世俗所傳歸藏易，偽書也。 易纂言卷首。</p>',13)])])}const f=p(n,[["render",r]]);export{m as __pageData,f as default};
